-- enums
create type public.app_role as enum ('super-admin', 'broker', 'agent', 'buyer', 'seller', 'owner', 'tenant');

-- functions
CREATE OR REPLACE FUNCTION public.address_book_profile_accessible(p_owner text, p_viewer uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
       select 1 from public.profiles o
       where o.id = nullif(p_owner, '')::uuid
         and (o.broker = p_viewer or o.id = p_viewer)
     );
$function$;

CREATE OR REPLACE FUNCTION public.admin_assign_broker(target_id uuid, broker_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_super_admin() then raise exception 'Super Admin access required'; end if;
  if target_id is null or not exists (select 1 from public.profiles where id = target_id) then raise exception 'Account not found'; end if;
  if broker_id is not null and not exists (select 1 from public.profiles where id = broker_id and role = 'broker' and registration_status = 'approved') then
    raise exception 'Broker not found or not approved';
  end if;
  update public.profiles set broker = broker_id where id = target_id;
  if not found then raise exception 'Profile not found'; end if;
  insert into public.audit_events (owner_id, event_type, entity_type, entity_id, detail)
  values (auth.uid(), 'assign_broker', 'profile', target_id::text, jsonb_build_object('broker', broker_id));
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_cancel_password_reset(target_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_cancelled integer;
begin
  if not public.is_super_admin() then raise exception 'Super Admin access required'; end if;
  if target_id is null or not exists (select 1 from public.password_resets where user_id = target_id and status = 'pending') then
    raise exception 'No pending reset request for this account';
  end if;
  update public.password_resets
  set status = 'cancelled', resolved_at = now()
  where user_id = target_id and status = 'pending';
  get diagnostics v_cancelled = row_count;
  insert into public.audit_events (owner_id, event_type, entity_type, entity_id, detail)
  values (auth.uid(), 'cancel_password_reset', 'profile', target_id::text, jsonb_build_object('status', 'cancelled'));
  return v_cancelled;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_list_password_resets()
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
  if not public.is_super_admin() then raise exception 'Super Admin access required'; end if;
  return query select jsonb_build_object(
      'id', r.id::text,
      'user_id', r.user_id::text,
      'email', r.email::text,
      'full_name', coalesce(p.full_name, '')::text,
      'created_at', r.created_at::text)
    from public.password_resets r
    left join public.profiles p on p.id = r.user_id
    where r.status = 'pending'
    order by r.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_list_profiles()
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
  if not public.is_super_admin() then raise exception 'Super Admin access required'; end if;
  return query select jsonb_build_object(
      'id', p.id::text,
      'full_name', p.full_name::text,
      'email', u.email::text,
      'role', p.role::text,
      'registration_status', p.registration_status::text,
      'requested_role', coalesce(u.raw_user_meta_data ->> 'requested_role', '')::text,
      'prc', p.prc::text,
      'resa', p.resa::text,
      'agency', p.agency::text,
      'broker', p.broker::text,
      'added_by', coalesce(u.raw_user_meta_data ->> 'created_by', '')::text,
      'added_by_role', coalesce(u.raw_user_meta_data ->> 'created_by_role', '')::text,
      'created_at', p.created_at::text)
    from public.profiles p join auth.users u on u.id = p.id
    order by case p.registration_status when 'pending' then 0 when 'approved' then 1 else 2 end, p.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_request_password_reset(p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid;
begin
  if p_email is null or btrim(p_email) = '' then return; end if;
  select id into v_user_id from auth.users where lower(email) = lower(btrim(p_email));
  if v_user_id is null then return; end if;
  if not exists (select 1 from public.password_resets where user_id = v_user_id and status = 'pending') then
    insert into public.password_resets (user_id, email, status) values (v_user_id, lower(btrim(p_email)), 'pending');
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_reset_password(target_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_password text;
begin
  if not public.is_super_admin() then raise exception 'Super Admin access required'; end if;
  if target_id is null or not exists (select 1 from public.profiles where id = target_id) then
    raise exception 'Account not found';
  end if;
  select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789',
      (1 + floor(random() * 58))::int, 1), '')
  into v_password from generate_series(1, 12);
  update auth.users
  set encrypted_password = extensions.crypt(v_password, extensions.gen_salt('bf')),
      raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) || '{"must_change_password":true}'::jsonb,
      updated_at = now()
  where id = target_id;
  update public.password_resets set status = 'done', resolved_at = now()
  where user_id = target_id and status = 'pending';
  insert into public.audit_events (owner_id, event_type, entity_type, entity_id, detail)
  values (auth.uid(), 'reset_password', 'profile', target_id::text, jsonb_build_object('must_change_password', true));
  return v_password;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_profile_access(target_id uuid, next_role app_role, next_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_super_admin() then raise exception 'Super Admin access required'; end if;
  if target_id = auth.uid() then raise exception 'You cannot change your own access'; end if;
  if next_status not in ('approved', 'rejected') then raise exception 'Invalid registration status'; end if;
  update public.profiles set role = next_role, registration_status = next_status where id = target_id;
  if not found then raise exception 'Profile not found'; end if;
  insert into public.audit_events (owner_id, event_type, entity_type, entity_id, detail)
  values (auth.uid(), 'registration_' || next_status, 'profile', target_id::text, jsonb_build_object('role', next_role));
end;
$function$;

CREATE OR REPLACE FUNCTION public.agent_cancel(p_task uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.agent_tasks
  set state = 'cancelled', lease_until = null, lease_id = null, completed_at = now()
  where id = p_task;
end;
$function$;

CREATE OR REPLACE FUNCTION public.agent_complete(p_task uuid, p_steps jsonb, p_next_due timestamp with time zone, p_next_reason text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t public.agent_tasks;
  step jsonb;
begin
  select * into t from public.agent_tasks where id = p_task for update;
  if t is null or t.state <> 'working' then
    raise exception 'Task % is not claimed/working', coalesce(p_task::text, 'null');
  end if;

  for step in select * from jsonb_array_elements(coalesce(p_steps, '[]'::jsonb)) loop
    insert into public.agent_steps (lead_id, task_id, kind, summary, detail, confident, done_by)
    values (
      coalesce(step ->> 'lead_id', t.lead_id),
      p_task,
      coalesce(step ->> 'kind', 'observation'),
      coalesce(step ->> 'summary', ''),
      coalesce(step -> 'detail', '{}'::jsonb),
      coalesce((step ->> 'confident')::boolean, false),
      coalesce(step ->> 'done_by', 'agent')
    );
  end loop;

  update public.agent_tasks
  set state = 'done', completed_at = now(), lease_until = null, lease_id = null
  where id = p_task;

  if p_next_due is not null and t.lead_id <> '' then
    insert into public.agent_tasks (lead_id, kind, reason, payload, task_meta, due_at, state)
    values (
      t.lead_id,
      'follow-up',
      coalesce(nullif(p_next_reason, ''), 'Scheduled follow-up'),
      jsonb_build_object('from_task', p_task, 'lead_id', t.lead_id),
      t.task_meta,
      p_next_due,
      'due'
    );
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.agent_set_step(p_step bigint, p_state text, p_by text DEFAULT 'agent'::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if p_state not in ('approved', 'rejected') then
    raise exception 'Step state must be approved or rejected';
  end if;
  update public.agent_steps
  set state = p_state, done_by = coalesce(nullif(p_by, ''), 'agent')
  where id = p_step;
end;
$function$;

CREATE OR REPLACE FUNCTION public.agent_snooze_lead(p_lead_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.agent_tasks
  set state = 'cancelled', lease_until = null, lease_id = null, completed_at = now()
  where lead_id = p_lead_id and state in ('due', 'working');
end;
$function$;

CREATE OR REPLACE FUNCTION public.broker_team()
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  me_role text;
begin
  select role::text into me_role from public.profiles where id = auth.uid();
  if me_role is distinct from 'broker' and me_role is distinct from 'super-admin' then
    raise exception 'Broker access required';
  end if;

  return query
    select jsonb_build_object(
      'id', p.id::text,
      'full_name', p.full_name::text,
      'email', u.email::text
    )
    from public.profiles p
    join auth.users u on u.id = p.id
    where p.role = 'agent'
      and p.registration_status = 'approved'
      and p.broker = auth.uid()
    order by p.full_name;
end;
$function$;

