CREATE OR REPLACE FUNCTION public.listing_payload_number(p_value text, p_min numeric, p_max numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  parsed numeric;
begin
  if coalesce(p_value, '') !~ '^-?\d+(\.\d+)?$' then return null; end if;
  parsed := p_value::numeric;
  if parsed < p_min or parsed > p_max then return null; end if;
  return parsed;
exception when numeric_value_out_of_range then
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.my_broker()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select jsonb_build_object(
    'id', b.id::text,
    'full_name', b.full_name::text,
    'email', u.email::text,
    'agency', coalesce(b.agency, '')::text,
    'prc', coalesce(b.prc, '')::text
  )
  from public.profiles me
  join public.profiles b on b.id = me.broker
  join auth.users u on u.id = b.id
  where me.id = auth.uid()
    and me.role = 'agent'
    and b.role = 'broker'
    and b.registration_status = 'approved';
$function$;

