CREATE OR REPLACE FUNCTION public.notify_on_cobroke_invite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target uuid;
        ltitle text;
begin
  select p.id into target
  from public.profiles p
  where lower(p.email) = lower(new.partner_email)
    and p.registration_status = 'approved'
  limit 1;

  if target is not null then
    update public.cobroke_agreements
      set selling_broker_id = target
      where id = new.id and selling_broker_id is null;
  end if;

  select s.title into ltitle from public.shared_listings s where s.id = new.listing_id;

  perform public.notify_user(
    coalesce(target, new.listing_broker_id),
    'info',
    'New co-broke invitation' || coalesce(' - ' || ltitle, ''),
    'Proposed split ' || new.split_selling_pct::text || '% for the selling broker.',
    'admin'
  );
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.notify_on_cobroke_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target uuid;
begin
  if new.status = old.status then return new; end if;
  target := case when new.selling_broker_id = auth.uid()
                 then new.listing_broker_id
                 else new.selling_broker_id end;
  if target is null then return new; end if;
  perform public.notify_user(
    target, 'info',
    'Co-broke ' || new.status,
    'Agreement status changed to "' || new.status || '".',
    'admin'
  );
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.notify_on_new_inquiry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare listing_owner uuid;
declare listing_title text;
begin
  select owner_id, title into listing_owner, listing_title
  from public.shared_listings where id = new.listing_id;
  if listing_owner is not null and listing_owner <> new.user_id then
    perform public.notify_user(
      listing_owner, 'inquiry',
      'New inquiry: ' || coalesce(listing_title, 'your listing'),
      coalesce(new.full_name, 'Someone') || ' (' || coalesce(new.contact_type, 'buyer') || ') is interested.',
      'listings'
    );
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.notify_on_registration_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous text := coalesce(old.registration_status, '');
begin
  if new.registration_status = old.registration_status then return new; end if;
  if new.registration_status = 'approved' then
    perform public.notify_user(
      new.id, 'approval',
      'Your account has been approved',
      'Welcome aboard! You can now sign in and use your assigned role.',
      'dashboard'
    );
  elsif new.registration_status = 'rejected' then
    perform public.notify_user(
      new.id, 'approval',
      'Your registration was declined',
      'Contact your ES Realty administrator for details.',
      ''
    );
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.notify_user(target_user uuid, n_type text, n_title text, n_body text, n_link text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if target_user is null then return; end if;
  insert into public.notifications (user_id, type, title, body, link_view)
  values (target_user, n_type, left(n_title, 200), left(n_body, 1000), left(coalesce(n_link, ''), 60));
end;
$function$;

CREATE OR REPLACE FUNCTION public.pms_books()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
  if not public.is_super_admin() then raise exception 'Super Admin access required' using errcode = '42501'; end if;
  return (
    select coalesce(jsonb_agg(row_to_json(x) order by x.company desc, x.name), '[]'::jsonb)
    from (
      select b.book_id,
             b.book_id = public.pms_company_book() as company,
             case when b.book_id = public.pms_company_book() then 'Company'
                  else coalesce(nullif(p.full_name, ''), u.email, b.book_id::text) end as name,
             p.registration_status as status,
             (select count(*) from public.pms_properties x where x.book_id = b.book_id and not x.archived) as properties,
             (select count(*) from public.pms_leases x where x.book_id = b.book_id and not x.archived) as leases
      from (
        select public.pms_company_book() as book_id
        union select book_id from public.pms_owners
        union select book_id from public.pms_tenants
        union select book_id from public.pms_properties
        union select book_id from public.pms_leases
      ) b
      left join public.profiles p on p.id = b.book_id
      left join auth.users u on u.id = b.book_id
    ) x
  );
end $function$;

CREATE OR REPLACE FUNCTION public.pms_can_manage(b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select b is not null and b = public.pms_my_book();
$function$;

CREATE OR REPLACE FUNCTION public.pms_company_book()
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
AS $function$ select '00000000-0000-0000-0000-000000000000'::uuid $function$;

CREATE OR REPLACE FUNCTION public.pms_find_login(p_email text, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare r record;
begin
  if public.pms_my_book() is null then
    raise exception 'Only brokers and super-admins can link logins' using errcode = '42501';
  end if;
  if p_role not in ('owner', 'tenant') then
    raise exception 'Only owner and tenant logins can be linked' using errcode = '22023';
  end if;
  select p.id, p.role::text as role, p.registration_status as status into r
  from public.profiles p join auth.users u on u.id = p.id
  where lower(u.email) = lower(trim(p_email))
  limit 1;
  insert into public.audit_events (owner_id, event_type, entity_type, entity_id, detail)
  values (auth.uid(), 'pms_find_login', 'profile', coalesce(r.id::text, ''), jsonb_build_object('role', p_role, 'found', r.id is not null));
  if r.id is null then return null; end if;
  if r.role <> p_role then return jsonb_build_object('other_role', true); end if;
  return jsonb_build_object('id', r.id, 'status', r.status);
end $function$;

CREATE OR REPLACE FUNCTION public.pms_is_staff()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.is_super_admin();
$function$;

CREATE OR REPLACE FUNCTION public.pms_login_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'role', p.role::text, 'status', p.registration_status)), '[]'::jsonb)
  from public.profiles p
  where public.pms_my_book() is not null
    and p.id in (
      select o.auth_user_id from public.pms_owners o where o.book_id = public.pms_my_book() and o.auth_user_id is not null
      union
      select t.auth_user_id from public.pms_tenants t where t.book_id = public.pms_my_book() and t.auth_user_id is not null);
$function$;

CREATE OR REPLACE FUNCTION public.pms_my_book()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case p.role::text
           when 'super-admin' then public.pms_company_book()
           when 'broker' then p.id
         end
  from public.profiles p
  where p.id = auth.uid() and p.registration_status = 'approved';
$function$;

CREATE OR REPLACE FUNCTION public.pms_my_lease_ids()
 RETURNS SETOF text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select l.id from public.pms_leases l
  where l.tenant_id in (select public.pms_my_tenant_ids());
$function$;

CREATE OR REPLACE FUNCTION public.pms_my_owner_ids()
 RETURNS SETOF text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select o.id from public.pms_owners o
  join public.profiles me on me.id = auth.uid()
  where o.auth_user_id = auth.uid() and not o.archived
    and me.role = 'owner' and me.registration_status = 'approved';
$function$;

CREATE OR REPLACE FUNCTION public.pms_my_property_ids()
 RETURNS SETOF text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
