  where p.owner_id in (select public.pms_my_owner_ids());
$function$;

CREATE OR REPLACE FUNCTION public.pms_my_tenant_ids()
 RETURNS SETOF text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select t.id from public.pms_tenants t
  join public.profiles me on me.id = auth.uid()
  where t.auth_user_id = auth.uid() and not t.archived
    and me.role = 'tenant' and me.registration_status = 'approved';
$function$;

CREATE OR REPLACE FUNCTION public.pms_owner_tenants()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', t.id, 'name', t.data ->> 'name', 'phone', t.data ->> 'phone',
    'email', t.data ->> 'email', 'owner_id', t.owner_id, 'archived', t.archived)), '[]'::jsonb)
  from public.pms_tenants t
  where t.owner_id in (select public.pms_my_owner_ids())
     or t.id in (select l.tenant_id from public.pms_leases l
                 where l.property_id in (select public.pms_my_property_ids()));
$function$;

CREATE OR REPLACE FUNCTION public.pms_same_book()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  j jsonb := to_jsonb(new);
  links text[] := array['owner_id:pms_owners', 'property_id:pms_properties', 'unit_id:pms_units', 'tenant_id:pms_tenants', 'lease_id:pms_leases'];
  l text; col text; tbl text; v text; b uuid;
begin
  if coalesce(current_setting('pms.transfer', true), '') = 'on' then return new; end if;
  if tg_op = 'UPDATE' and new.book_id is distinct from old.book_id then
    raise exception 'A PMS record cannot move to another book' using errcode = '42501';
  end if;
  foreach l in array links loop
    col := split_part(l, ':', 1); tbl := split_part(l, ':', 2);
    v := j ->> col;
    if v is not null and v <> '' then
      execute format('select book_id from public.%I where id = $1', tbl) into b using v;
      if b is not null and b <> new.book_id then
        raise exception 'PMS records from different books cannot be linked (%.%)', tg_table_name, col using errcode = '42501';
      end if;
    end if;
  end loop;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.pms_tenant_landlords()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', o.id, 'name', o.data ->> 'name', 'company', o.data ->> 'company',
    'phone', o.data ->> 'phone', 'email', o.data ->> 'email', 'archived', o.archived)), '[]'::jsonb)
  from public.pms_owners o
  where o.id in (select l.owner_id from public.pms_leases l where l.id in (select public.pms_my_lease_ids()))
     or o.id in (select p.owner_id from public.pms_properties p
                 join public.pms_leases l on l.property_id = p.id
                 where l.id in (select public.pms_my_lease_ids()));
$function$;

CREATE OR REPLACE FUNCTION public.pms_transfer_book(p_from uuid, p_to uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t text; n bigint; counts jsonb := '{}'::jsonb;
begin
  if not public.is_super_admin() then raise exception 'Super Admin access required' using errcode = '42501'; end if;
  if p_from is null or p_to is null or p_from = p_to then raise exception 'Choose two different books' using errcode = '22023'; end if;
  if p_to <> public.pms_company_book() and not exists (
    select 1 from public.profiles where id = p_to and role::text = 'broker' and registration_status = 'approved') then
    raise exception 'The new book must be the company or an approved broker' using errcode = '22023';
  end if;
  perform set_config('pms.transfer', 'on', true);
  foreach t in array array['pms_owners','pms_tenants','pms_properties','pms_units','pms_leases','pms_payments','pms_maintenance','pms_expenses','pms_documents'] loop
    execute format('update public.%I set book_id = $1, updated_by = auth.uid() where book_id = $2', t) using p_to, p_from;
    get diagnostics n = row_count;
    counts := counts || jsonb_build_object(t, n);
  end loop;
  perform set_config('pms.transfer', '', true);
  insert into public.audit_events (owner_id, event_type, entity_type, entity_id, detail)
  values (auth.uid(), 'pms_transfer_book', 'pms_book', p_from::text, jsonb_build_object('to', p_to, 'moved', counts));
  return counts;
end $function$;

CREATE OR REPLACE FUNCTION public.profiles_protect_licence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (new.prc is distinct from old.prc or new.resa is distinct from old.resa)
     and old.registration_status = 'approved'
     and auth.uid() is not null            -- the service role and SQL editor have no user
     and not public.is_super_admin() then
    raise exception 'Your PRC and RESA numbers have been verified. Ask a super-admin to change them.'
      using errcode = '42501';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at = now(); return new; end; $function$;

CREATE OR REPLACE FUNCTION public.swap_sales_playbook_order(first_id uuid, second_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  first_order integer;
  second_order integer;
begin
  if not public.is_super_admin() then
    raise exception 'Super Admin access required';
  end if;

  select sort_order into first_order
  from public.sales_playbooks
  where id = first_id
  for update;

  select sort_order into second_order
  from public.sales_playbooks
  where id = second_id
  for update;

  if first_order is null or second_order is null then
    raise exception 'Playbook not found';
  end if;

  update public.sales_playbooks
  set sort_order = case
    when id = first_id then second_order
    when id = second_id then first_order
    else sort_order
  end
  where id in (first_id, second_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_profile_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.profiles
  set email = lower(new.email)
  where id = new.id
    and email is distinct from lower(new.email);
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_shared_listing_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  payload_changed boolean;
begin
  if tg_op = 'INSERT' then
    payload_changed := true;
  else
    payload_changed := new.payload is distinct from old.payload;
  end if;

  if payload_changed then
    new.description := coalesce(new.payload ->> 'description', new.description, '');
    new.property_type := coalesce(nullif(new.payload ->> 'propertyType', ''), new.property_type, 'house-and-lot');
    new.offer_type := coalesce(nullif(new.payload ->> 'dealType', ''), new.offer_type, 'sale');
    new.address := coalesce(new.payload ->> 'address', new.address, '');
    new.barangay := coalesce(new.payload ->> 'barangay', new.barangay, '');
    new.city := coalesce(new.payload ->> 'city', new.city, '');
    new.province := coalesce(new.payload ->> 'province', new.province, '');
    new.region := coalesce(new.payload ->> 'region', new.region, '');
    new.postal_code := coalesce(new.payload ->> 'postalCode', new.payload ->> 'zip', new.postal_code, '');
    new.price := coalesce(public.listing_payload_number(new.payload ->> 'price', 0, 9999999999999.99), new.price, 0);
    new.rent := coalesce(public.listing_payload_number(new.payload ->> 'rent', 0, 9999999999999.99), new.rent, 0);
    if new.payload ? 'lat' then new.latitude := public.listing_payload_number(new.payload ->> 'lat', -90, 90); end if;
    if new.payload ? 'lng' then new.longitude := public.listing_payload_number(new.payload ->> 'lng', -180, 180); end if;
    new.bedrooms := coalesce(public.listing_payload_number(new.payload ->> 'bedrooms', 0, 32767)::smallint, new.bedrooms, 0);
    new.bathrooms := coalesce(public.listing_payload_number(new.payload ->> 'bathrooms', 0, 99.9), new.bathrooms, 0);
    if new.payload ? 'floorArea' then new.floor_area_sqm := public.listing_payload_number(new.payload ->> 'floorArea', 0, 9999999999.99); end if;
    if new.payload ? 'lotArea' then new.lot_size_sqm := public.listing_payload_number(new.payload ->> 'lotArea', 0, 9999999999.99); end if;
    if new.payload ? 'yearBuilt' then new.year_built := public.listing_payload_number(new.payload ->> 'yearBuilt', 1600, 2200)::smallint; end if;
    if new.payload ? 'featured' then
      new.featured := case lower(coalesce(new.payload ->> 'featured', ''))
        when 'true' then true when 'false' then false else new.featured end;
    end if;
  end if;
  if tg_op = 'INSERT' then
    if new.is_published then new.published_at := now(); end if;
  elsif new.is_published and not coalesce(old.is_published, false) then
    new.published_at := now();
  elsif not new.is_published then
    new.published_at := null;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_shared_listing_images()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.payload ? 'photos' and jsonb_typeof(new.payload -> 'photos') = 'array' then
    delete from public.listing_images where listing_id = new.id;
    insert into public.listing_images (listing_id, url, display_order)
    select new.id, photo.url, (min(photo.position) - 1)::integer
    from jsonb_array_elements_text(new.payload -> 'photos') with ordinality as photo(url, position)
    where btrim(photo.url) <> ''
    group by photo.url;
  end if;
  return new;
end;
$function$;

