-- tables
create table if not exists public.agent_steps (id bigint generated always as identity not null, lead_id text default ''::text not null, task_id uuid, kind text not null, summary text default ''::text not null, detail jsonb default '{}'::jsonb not null, confident boolean default false not null, state text default 'open'::text not null, done_by text default 'agent'::text not null, created_at timestamp with time zone default now() not null);

