create table if not exists public.cash_entries (id uuid default gen_random_uuid() not null, owner_id uuid not null, account_id uuid not null, entry_date date default CURRENT_DATE not null, direction text not null, amount numeric(14,2) not null, category text default ''::text not null, purpose text default ''::text not null, subcategory text default ''::text not null, description text default ''::text not null, counterparty text default ''::text not null, reference_no text default ''::text not null, linked_asset_id text default ''::text not null, linked_construction_id uuid, linked_phase_id uuid, linked_presell_project_id uuid, linked_presell_payment_id text default ''::text not null, linked_transaction_id text default ''::text not null, proof_required boolean default false not null, status text default 'posted'::text not null, reversal_of uuid, idempotency_key text default ''::text not null, created_by uuid, approved_by uuid, posted_at timestamp with time zone, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);

create table if not exists public.cobroke_agreements (id uuid default gen_random_uuid() not null, listing_id text not null, listing_broker_id uuid not null, selling_broker_id uuid, partner_email text default ''::text not null, split_listing_pct numeric(5,2) default 50 not null, split_selling_pct numeric(5,2) default 50 not null, status text default 'proposed'::text not null, notes text default ''::text not null, responded_at timestamp with time zone, completed_at timestamp with time zone, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);

