create table if not exists public.construction_change_orders (id uuid default gen_random_uuid() not null, project_id uuid not null, amount numeric(14,2) not null, reason text not null, approver text default ''::text not null, co_date date default CURRENT_DATE not null, status text default 'approved'::text not null, created_by uuid, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);

