-- views
create or replace view public.public_listing_catalog with (security_barrier=true, security_invoker=true) as  SELECT listing.id,
    listing.ref,
    listing.title,
    listing.description,
    listing.property_type,
    listing.offer_type,
    listing.status,
    listing.price,
    listing.rent,
    listing.address,
    listing.barangay,
    listing.city,
    listing.province,
    listing.region,
    listing.postal_code,
    listing.latitude,
    listing.longitude,
    listing.bedrooms,
    listing.bathrooms,
    listing.floor_area_sqm,
    round(listing.floor_area_sqm * 10.7639, 2) AS floor_area_sqft,
    listing.lot_size_sqm,
    round(listing.lot_size_sqm * 10.7639, 2) AS lot_size_sqft,
    listing.year_built,
    listing.featured,
    listing.owner_id AS agent_id,
    profile.full_name AS agent_name,
    listing.views,
    listing.inquiries,
    listing.published_at,
    listing.updated_at,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', image.id, 'url', image.url, 'altText', image.alt_text, 'displayOrder', image.display_order) ORDER BY image.display_order, image.created_at) AS jsonb_agg
           FROM listing_images image
          WHERE image.listing_id = listing.id), '[]'::jsonb) AS images,
        CASE
            WHEN listing.offer_type = 'rent'::text THEN listing.rent
            ELSE listing.price
        END AS display_price
   FROM shared_listings listing
     LEFT JOIN profiles profile ON profile.id = listing.owner_id
  WHERE listing.is_published;

-- functions that return table rows
CREATE OR REPLACE FUNCTION public.agent_claim_due(p_max integer DEFAULT 10)
 RETURNS SETOF agent_tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
    update public.agent_tasks t
    set state = 'working',
        lease_id = gen_random_uuid(),
        lease_until = now() + interval '5 minutes'
    where t.id in (
      select id from public.agent_tasks
      where (state = 'due'
             and due_at <= now()
             and (lease_until is null or lease_until < now()))
         or (state = 'working' and lease_until < now())
      order by due_at
      limit greatest(1, p_max)
      for update skip locked
    )
    returning t.*;
end;
$function$;

CREATE OR REPLACE FUNCTION public.ensure_my_profile()
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  result public.profiles;
begin
  insert into public.profiles (id, full_name, email)
  values (auth.uid(),
          coalesce(auth.jwt() -> 'user_metadata' ->> 'full_name', ''),
          lower(nullif(auth.jwt() ->> 'email', '')))
  on conflict (id) do nothing;
  select * into result from public.profiles where id = auth.uid();
  return result;
end;
$function$;

