create policy "documents read own folder" on storage.objects as permissive for select to public using (((bucket_id = 'private-documents'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));

create policy "documents read shared transaction" on storage.objects as permissive for select to public using (((bucket_id = 'private-documents'::text) AND ((storage.foldername(name))[2] = 'tx'::text) AND (EXISTS ( SELECT 1
   FROM broker_transactions t
  WHERE (t.id = (storage.foldername(objects.name))[3])))));

create policy "documents update own folder" on storage.objects as permissive for update to public using (((bucket_id = 'private-documents'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));

create policy "listing photos insert own folder" on storage.objects as permissive for insert to authenticated with check (((bucket_id = 'listing-photos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1]) AND (listing_current_user_can_publish() OR is_super_admin())));

create policy "listing photos update own folder" on storage.objects as permissive for update to authenticated using (((bucket_id = 'listing-photos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1]) AND (listing_current_user_can_publish() OR is_super_admin())));

create policy "pms receipts linked read" on storage.objects as permissive for select to authenticated using (((bucket_id = 'pms-receipts'::text) AND (EXISTS ( SELECT 1
   FROM pms_payments p
  WHERE ((p.id = (storage.foldername(objects.name))[2]) AND (NOT p.archived))))));

create policy "pms receipts manager write" on storage.objects as permissive for all to authenticated using (((bucket_id = 'pms-receipts'::text) AND (((storage.foldername(name))[1] = (pms_my_book())::text) OR (((storage.foldername(name))[1] = 'payments'::text) AND (pms_my_book() = pms_company_book())) OR (EXISTS ( SELECT 1
   FROM pms_payments p
  WHERE ((p.id = (storage.foldername(objects.name))[2]) AND pms_can_manage(p.book_id))))))) with check (((bucket_id = 'pms-receipts'::text) AND (((storage.foldername(name))[1] = (pms_my_book())::text) OR (((storage.foldername(name))[1] = 'payments'::text) AND (pms_my_book() = pms_company_book())) OR (EXISTS ( SELECT 1
   FROM pms_payments p
  WHERE ((p.id = (storage.foldername(objects.name))[2]) AND pms_can_manage(p.book_id)))))));

